[STAThread]static void Main(string[] args){new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Directory.CreateDirectory(args[0]);var asm=typeof(Pilot).Assembly;int checks=0;string advice="";string[] languages={"it","en","es","fr","de","pt"};using(var r=new StreamReader(asm.GetManifestResourceStream("HdrTranslations.tsv"))){while(!r.EndOfStream){string line=r.ReadLine();if(line.StartsWith("#")||String.IsNullOrWhiteSpace(line))continue;var cells=line.Split('\t');if(cells[0].StartsWith("Modello riconosciuto"))advice=cells[0].Replace("{0}","1060");for(int source=0;source<6;source++)for(int target=0;target<6;target++){string value;Check(HdrTranslations.TryTranslate(cells[source].Replace("{0}","1234"),languages[target],out value),"missing "+cells[source]);Check(value==cells[target].Replace("{0}","1234"),"wrong placeholder "+value);checks++;}}}
