foreach(string lang in languages){Core.Pref.Language=lang;string translated=Appearance.Localize(raw);Check(lang=="it"||!translated.Contains("Stato lettore"),"nested prefix");Check(lang=="en"||!translated.Contains(error),"nested error");Check(Appearance.Localize(path)==path,"path changed");Check(!Appearance.Localize("File letti · HDR richiesto: False. I campi assenti usano il profilo iniziale; eventuali decimali sono arrotondati nel pannello.").Contains("{0}"),"file state");foreach(int width in new[]{1180,3440}){Window w;using(var stream=asm.GetManifestResourceStream("Main.xaml"))w=(Window)XamlReader.Load(stream);w.ShowActivated=false;w.Left=-10000;w.Top=-10000;w.Width=width;w.Height=width==1180?740:1440;((FrameworkElement)w.FindName("FeatureHome")).Visibility=Visibility.Collapsed;((FrameworkElement)w.FindName("HdrSettings")).Visibility=Visibility.Visible;((TextBlock)w.FindName("MonitorAdvice")).Text=advice;((TextBlock)w.FindName("ReaderStatus")).Text=raw;((TextBlock)w.FindName("ReadState")).Text="File letti · HDR richiesto: False. I campi assenti usano il profilo iniziale; eventuali decimali sono arrotondati nel pannello.";w.Show();Appearance.Refresh();w.UpdateLayout();var scroll=(ScrollViewer)w.FindName("HdrScroll");scroll.ScrollToBottom();w.UpdateLayout();Check(((TextBlock)w.FindName("ReaderStatus")).Text==translated,"UI translation");Appearance.Refresh();Check(((TextBlock)w.FindName("ReaderStatus")).Text==translated,"repeat refresh changed text");var image=new RenderTargetBitmap(width,(int)w.Height,96,96,PixelFormats.Pbgra32);image.Render(w);var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(image));using(var f=File.Create(Path.Combine(args[0],lang+"-"+width+".png")))enc.Save(f);Core.Pref.Language="it";Appearance.Refresh();Check(((TextBlock)w.FindName("ReaderStatus")).Text==Appearance.Localize(raw),"switch back to Italian");Core.Pref.Language=lang;w.Close();}}
